import { upstreamOracleImports } from "../transformSource.mjs";
import {readFileSync,writeFileSync} from 'node:fs';
import {resolve,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const {checkout}=JSON.parse(readFileSync(resolve(root,'.work/source.json'),'utf8'));
const target=resolve(checkout,'apps/web/src/components/chat');
const snapshot=JSON.parse(readFileSync(resolve(root,'tests/timeline-corpus.json'),'utf8'));
const projector=readFileSync(resolve(root,'src/projectNativeSnapshot.ts'),'utf8').replace(/import type .*from '\.\/bridge';\n/,'type ConversationSnapshot = any;\n').replaceAll("'@conversation-source/session-logic'","'../../session-logic'").replaceAll("'@conversation-source/components/chat/MessagesTimeline.logic'","'./MessagesTimeline.logic'").replaceAll("'@conversation-source/types'","'../../types'");
writeFileSync(resolve(target,'TabNativeProjection.fixture.ts'),upstreamOracleImports(projector));
const script=`import {expect,it} from 'vite-plus/test';
import {page} from 'vite-plus/test/browser';
import {createRef} from 'react';
import {Atom,AsyncResult} from 'effect/reactivity';
import {appendTerminalOutput,EMPTY_TERMINAL_OUTPUT} from '@conversation/shared/terminalOutput';
import {render} from '../../../test/render';
import {MessagesTimeline} from './MessagesTimeline';
import {AppAtomRegistryProvider} from '../../rpc/atomRegistry';
import {observeResize} from '../../lib/observeResize';
import {applyAppearanceFontVariables} from '../../appearanceFonts';
import {projectNativeSnapshot} from './TabNativeProjection.fixture';
import '~/index.css';
const snapshot=${JSON.stringify(snapshot)};
const standardNotification=(event:ErrorEvent)=>event.error==null&&/^ResizeObserver loop (?:completed with undelivered notifications\\.?|limit exceeded\\.?)$/.test(event.message);
it('actual source timeline resize notifications settle after expansion',async()=>{
 const events:Array<{message:string;hasError:boolean}>=[];
 const listener=(event:ErrorEvent)=>{events.push({message:event.message,hasError:event.error!=null});if(standardNotification(event))event.preventDefault();};
 window.addEventListener('error',listener);
 await page.viewport(900,1100);document.documentElement.classList.remove('dark');
 applyAppearanceFontVariables(document.documentElement,{sans:'',code:'',composer:'',sizeInterface:16,sizePrompt:14,sizeCode:13,smoothing:true,separate:false});
 const projection=projectNativeSnapshot(snapshot);
 const detail=Atom.family((itemId:string)=>Atom.make(AsyncResult.success({item:projection.toolItems.get(itemId)})));const output=Atom.family((itemId:string)=>Atom.make(AsyncResult.success({output:appendTerminalOutput(EMPTY_TERMINAL_OUTPUT,projection.toolItems.get(itemId)?.output??''),running:false})));
 const source={detail:(input:any)=>detail(input.itemId),commandOutput:(input:any)=>output(input.itemId)};
 const props:any={...projection,listRef:createRef(),turnItemSource:source,isWorking:false,routeThreadKey:'project:timeline-parity',activeThreadEnvironmentId:'project',markdownCwd:'/workspace',workspaceRoot:'/workspace',resolvedTheme:'light',timestampFormat:'locale',supportsConversationRollback:false,isRevertingCheckpoint:false,onOpenThread:()=>{},onRevertToTurnCount:()=>{},onImageExpand:()=>{},anchorMessageId:null,onAnchorReady:()=>{},onAnchorSizeChanged:()=>{},contentInsetEndAdjustment:0,emptyPlaceholderInset:0,liveFollowEnabled:true,onIsAtEndChange:()=>{}};
 await using screen=await render(<div style={{height:'100vh',minHeight:0}} className="bg-background text-foreground"><AppAtomRegistryProvider><MessagesTimeline {...props}/></AppAtomRegistryProvider></div>);
 await expect.element(screen.getByRole('heading',{name:'Final result'})).toBeVisible();
 await screen.getByRole('button',{name:/Worked for|Completed work/i}).first().click();
 const aggregate=screen.getByRole('button',{name:/Ran 1 command and used 1 tool/i});
 await expect.element(aggregate).toBeVisible();await aggregate.click();
 await screen.getByRole('button',{name:/printf hello/i}).first().click();
 await expect.poll(()=>screen.container.querySelector('.max-h-80')).toBeTruthy();
 await page.viewport(360,1100);await new Promise(resolve=>setTimeout(resolve,150));
 await page.viewport(800,1100);await new Promise(resolve=>setTimeout(resolve,300));
 const geometry=()=>Array.from(screen.container.querySelectorAll('[data-tool-group-scroll],.messages-timeline-scroll,.chat-markdown')).map(node=>{const rect=node.getBoundingClientRect();return [rect.x,rect.y,rect.width,rect.height];});
 const stable=geometry();const settledEvents=events.length;
 await new Promise(resolve=>setTimeout(resolve,500));
 expect(geometry()).toEqual(stable);expect(events.length).toBe(settledEvents);
 // The same source observer can queue a standard no-exception notification when a callback changes size once.
 const probe=document.createElement('div');probe.style.cssText='width:100px;height:20px';screen.container.append(probe);let changed=false;
 const stop=observeResize(probe,()=>{if(!changed){changed=true;probe.style.height='24px';}});
 await new Promise(resolve=>setTimeout(resolve,100));stop();probe.remove();
 expect(changed).toBe(true);expect(events.some(event=>event.message.startsWith('ResizeObserver loop')&&!event.hasError)).toBe(true);
 expect(events.filter(event=>event.hasError)).toEqual([]);
 await expect(JSON.stringify({interactionEvents:settledEvents,totalEvents:events.length,events,stableGeometry:stable},null,2)).toMatchFileSnapshot('./__snapshots__/tab-source-timeline-resize.json');
 window.removeEventListener('error',listener);
});`;
writeFileSync(resolve(target,'TabSourceTimelineResize.browser.test.tsx'),upstreamOracleImports(script));
console.log('Wrote actual-source MessagesTimeline resize fixture');
